Sorry, cannot repeat. I converted your code into plain C and used the following verbatim with no valgrind warnings and no memory leaks. Can you tell me what I need to change to make it crash?

What libcurl version are you using?

```
#include <curl/curl.h>

#define URL  "http://localhost/"

static size_t readcallback(char *buffer, size_t size, size_t nitems, void *instream)
{
   return 0;
}

int main(int argc, char **argv)
{
   struct curl_httppost *formpost = NULL;
   struct curl_httppost *lastptr = NULL;
   CURL * handle = NULL;
   struct curl_slist * headerlist = NULL;
   const char* fn = "filename";
   char space2[17];   // 17 is the sweet spot
   char space[8+8+8];


   curl_global_init(CURL_GLOBAL_ALL);

   handle = (curl_easy_init());
   headerlist = (curl_slist_append(NULL,"Expect:"));

   // we don't want "Expect: 100-continue" -- it screws up proxy
   curl_easy_setopt(handle, CURLOPT_HTTPHEADER, headerlist);

   curl_easy_setopt(handle, CURLOPT_URL, URL);
   curl_easy_setopt(handle, CURLOPT_VERBOSE, 1L);

   curl_easy_setopt(handle, CURLOPT_READFUNCTION, readcallback);

   // authentication (at the server end)
   curl_easy_setopt(handle, CURLOPT_HTTPAUTH, CURLAUTH_ANYSAFE);
   curl_easy_setopt(handle, CURLOPT_USERNAME, "");
   curl_easy_setopt(handle, CURLOPT_PASSWORD, "");

   curl_formadd( &formpost, &lastptr,
                 CURLFORM_COPYNAME, "file",

                 CURLFORM_STREAM, (void*)0x121,
                 CURLFORM_CONTENTSLENGTH, 0,//reader_data.size,
                 CURLFORM_FILENAME, fn,

                 CURLFORM_END
     );

   curl_easy_setopt(handle, CURLOPT_HTTPPOST, formpost);
   curl_easy_perform(handle);

   curl_easy_cleanup(handle);

   curl_slist_free_all(headerlist);
   curl_formfree(formpost);

   // should die by now
   return 0;
}
```

Hello @bagder,

Although the code execution path has been identified, but I don't have a way to 100% reproduce the issue. In my company, the issue can be occasionally reproduced using [Baidu PCS API](http://developer.baidu.com/wiki/index.php?title=docs/pcs/rest/file_data_apis_list) to upload a large file to Baidu server with chunks.

The patch below is a temporary fix that I mentioned earlier based on the method used in db6ff224f8ac1ffb0c99ad6ce17e32d30e463e9c and has been committed to our company's repository. Personally I think a better way of fixing the issue is to extend the <code>backup</code> member by adding a type: 
- The initial state of backup type is BACKUP_EMPTY.
- Before switching <code>fread_func</code> to <code>readmoredata</code>, backup all pointers to the <code>backup</code> structure and set the type to BACKUP_REDEMOREDATA. The type is set to BACKUP_EMPTY after the pointers are restored.
- Likewise, backup all pointers and set the backup type to BACKUP_FORMREADER before switching <code>fread_func</code> to <code>Curl_FormReader</code>. To unify the logic, you can instead switch the <code>fread_func</code> to another static function that calls <code>Curl_FormReader</code> and restores the pointers and backup type back to initial state before returning. With the static function, all pointers are restored earlier and the restoration becomes safer because it is not delayed to <code>Curl_http_done</code>.
- Finally, the only thing needs to be make sure is that the type of backup can never be overlapped. In other words you can't backup both pointers types at the same time. But currently the condition will always hold because <code>readmoredata</code> is called only if the HTTP request type is <code>HTTPREQ_POST</code> and <code>Curl_FormReader</code> is called if HTTP request type is <code>HTTPREQ_POST_FORM</code>. So basically their code paths are different.

The suggestion above is quite long, if you need me to write it as a patch, please let me know and I'll submit to you later as I am not that familiar with open source code contributing.

``` patch
diff --git a/lib/http.c b/lib/http.c
index fe2c2ca..6008029 100644
--- a/lib/http.c
+++ b/lib/http.c
@@ -1486,6 +1486,17 @@ CURLcode Curl_http_done(struct connectdata *conn,
 #endif

   /* set the proper values (possibly modified on POST) */
+  if (http->curl_7_43_backup.fread_func) {
+    data->set.fread_func = http->curl_7_43_backup.fread_func; /* restore */
+    http->curl_7_43_backup.fread_func = NULL;
+  }
+  if (http->curl_7_43_backup.fread_in) {
+    data->set.in = http->curl_7_43_backup.fread_in; /* restore */
+    http->curl_7_43_backup.fread_in = NULL;
+  }
+
   conn->seek_func = data->set.seek_func; /* restore */
   conn->seek_client = data->set.seek_client; /* restore */

@@ -2453,6 +2464,11 @@ CURLcode Curl_http(struct connectdata *conn, bool *done)
        stream. */
     http->form.fread_func = data->set.fread_func;

+    /* backup fread_func and in, will be restored on done */
+    http->curl_7_43_backup.fread_func = data->set.fread_func;
+    http->curl_7_43_backup.fread_in = data->set.in;
+
     /* Set the read function to read from the generated form data */
     data->set.fread_func = (curl_read_callback)Curl_FormReader;
     data->set.in = &http->form;
diff --git a/lib/http.h b/lib/http.h
index 415be39..0437753 100644
--- a/lib/http.h
+++ b/lib/http.h
@@ -144,6 +144,13 @@ struct HTTP {
     curl_off_t postsize;
   } backup;
+
+  // FIXME: fix curl 7.43 update regression, issue #346
+  struct fix_curl_7_43_back {
+    curl_read_callback fread_func;
+    void *fread_in;
+  } curl_7_43_backup;
+
   enum {
     HTTPSEND_NADA,    /* init */
     HTTPSEND_REQUEST, /* sending a request */
```
